"""Seam coverage for the CapsLock/Shift state refresh (upstream #683).

``cbTS.capsStates`` used to be written only at init and on language-button
updates, so a key-up dropped by the host pinned the reported case for the rest
of the session. The engine now re-derives it from the real key state on every
key event; the explicit language-button update path keeps working.

The hardware is faked through ``CinBase.getKeyState`` so a dropped key-up can be
simulated: the value flips between two key events with no key-up in between.
"""

import os
import sys
import unittest

ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), os.path.pardir))
for _path in (os.path.join(ROOT, "python"), os.path.dirname(os.path.abspath(__file__))):
    if _path not in sys.path:
        sys.path.insert(0, _path)

from test_cinbase_shift_to_english import CinbaseKeyHarness  # noqa: E402

VK_SHIFT = 0x10


class _CapsFake:
    """Stand-in for ``ctypes.WinDLL('User32.dll').GetKeyState`` toggling."""

    def __init__(self, value):
        self.value = value
        self.calls = 0

    def __call__(self, keyCode):
        self.calls += 1
        return self.value


class CinbaseCapsStateTests(CinbaseKeyHarness):

    def install_caps(self, value):
        import cinbase
        fake = _CapsFake(value)
        original = cinbase.CinBase.getKeyState
        cinbase.CinBase.getKeyState = fake
        self.addCleanup(setattr, cinbase.CinBase, "getKeyState", original)
        return fake

    def letter_with_shift(self, service):
        # 真實的 TSF 按鍵：keyCode 是 VK_B (0x42)，charCode 是 'B' (也是 0x42)
        return self.send(service, ord("B"), 0x42, printable=True, shift=True)

    def test_caps_case_follows_the_hardware_per_key(self):
        fake = self.install_caps(False)
        service = self.activate_chesimplex()
        service.outputSmallLetterWithShift = True

        self.assertEqual(self.letter_with_shift(service), "b")

        # CapsLock was turned on; no key-up for it ever reaches the engine.
        fake.value = True
        self.assertEqual(self.letter_with_shift(service), "B")
        self.assertTrue(service.capsStates)

        fake.value = False
        self.assertEqual(self.letter_with_shift(service), "b")
        self.assertFalse(service.capsStates)
        self.assertGreater(fake.calls, 1, "the key state was never re-read")

    def test_dropped_keyup_does_not_pin_the_state(self):
        fake = self.install_caps(True)
        service = self.activate_chesimplex()
        service.outputSmallLetterWithShift = True

        self.assertEqual(self.letter_with_shift(service), "B")
        # The CapsLock key-up is dropped by the host: only the following
        # key-downs arrive, and each must re-derive the state.
        fake.value = False
        self.assertEqual(self.letter_with_shift(service), "b")
        fake.value = True
        self.assertEqual(self.letter_with_shift(service), "B")

    def test_language_button_update_still_refreshes(self):
        fake = self.install_caps(False)
        service = self.activate_chesimplex()
        self.assertFalse(service.capsStates)

        fake.value = True
        service.cinbase.updateLangButtons(service)
        self.assertTrue(service.capsStates)

        fake.value = False
        service.cinbase.updateLangButtons(service)
        self.assertFalse(service.capsStates)


if __name__ == "__main__":
    unittest.main()
